<form method="post" enctype="multipart/form-data" action="<?= e(url('admin/?action=save_post&id='.($post['id'] ?? 0))) ?>"><h1><?= $post?'Edit':'Create' ?> Post</h1><?= csrf_field() ?><input type="hidden" name="existing_image" value="<?= e($post['featured_image'] ?? '') ?>"><input name="title" required value="<?= e($post['title'] ?? '') ?>" placeholder="Title"><input name="slug" value="<?= e($post['slug'] ?? '') ?>" placeholder="Slug"><select name="category_id"><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (($post['category_id'] ?? 0)==$c['id'])?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><input type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"><textarea name="short_description" placeholder="Short description"><?= e($post['short_description'] ?? '') ?></textarea><textarea name="content" required rows="10"><?= e($post['content'] ?? '') ?></textarea><input name="meta_title" value="<?= e($post['meta_title'] ?? '') ?>" placeholder="Meta title"><input name="meta_description" value="<?= e($post['meta_description'] ?? '') ?>" placeholder="Meta description"><input name="meta_keywords" value="<?= e($post['meta_keywords'] ?? '') ?>" placeholder="Meta keywords"><input type="date" name="publish_date" value="<?= e(isset($post['publish_at'])?substr($post['publish_at'],0,10):date('Y-m-d')) ?>"><input type="time" name="publish_time" value="<?= e(isset($post['publish_at'])?substr($post['publish_at'],11,5):date('H:i')) ?>"><select name="status"><option value="draft">Draft</option><option value="published" <?= (($post['status'] ?? '')==='published')?'selected':'' ?>>Published</option></select><button>Save</button></form>
